import{_ as e,k as t,v as n}from"./app-Xgp6P-Ux.js";import{t as r}from"./plugin-vue_export-helper-BDNMzG2s.js";import"./gzh-BO4QB3XE.js";import"./zsxq-BKcsYlFO.js";var i=JSON.parse(`{"path":"/column/%E6%95%B0%E6%8D%AE%E5%88%86%E6%9E%90%E6%80%9D%E7%BB%B4%E4%B8%8E%E5%AE%9E%E6%88%9823%E8%AE%B2/23.html","title":"22-用户研究：用户研究和数据分析的根本联系与区别","lang":"zh-CN","frontmatter":{"title":"22-用户研究：用户研究和数据分析的根本联系与区别","icon":"blog","date":"2025-09-25T23:11:07.000Z","author":"bornforthis","isOriginal":true,"sticky":false,"star":false,"article":true,"timeline":true,"image":false,"navbar":true,"sidebarIcon":true,"comment":true,"lastUpdated":true,"editLink":true,"backToTop":true,"toc":true,"description":"今天我主要介绍用户研究，用户研究是分析师日常必须要掌握的一项技能。 本课时内容分为三部分： 什么是用户研究； 用户研究的步骤和关键点； 用户研究的注意事项； 1. 什么是用户研究 用户研究是一种职业意识，任何人都应该具备用户研究思维，包括以下方面。 1.1 这个功能能满足用户什么需求？ 大部分 App 都是抄来抄去，这就是没想清楚这个功能能满足用户什么...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"22-用户研究：用户研究和数据分析的根本联系与区别\\",\\"image\\":[\\"https://bornforthis.cn/gzh.jpg\\",\\"https://bornforthis.cn/zsxq.jpg\\"],\\"datePublished\\":\\"2025-09-25T23:11:07.000Z\\",\\"dateModified\\":\\"2025-09-26T00:51:48.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"bornforthis\\"}]}"],["meta",{"property":"og:url","content":"https://bornforthis.cn/column/%E6%95%B0%E6%8D%AE%E5%88%86%E6%9E%90%E6%80%9D%E7%BB%B4%E4%B8%8E%E5%AE%9E%E6%88%9823%E8%AE%B2/23.html"}],["meta",{"property":"og:site_name","content":"AI悦创-Python一对一辅导"}],["meta",{"property":"og:title","content":"22-用户研究：用户研究和数据分析的根本联系与区别"}],["meta",{"property":"og:description","content":"今天我主要介绍用户研究，用户研究是分析师日常必须要掌握的一项技能。 本课时内容分为三部分： 什么是用户研究； 用户研究的步骤和关键点； 用户研究的注意事项； 1. 什么是用户研究 用户研究是一种职业意识，任何人都应该具备用户研究思维，包括以下方面。 1.1 这个功能能满足用户什么需求？ 大部分 App 都是抄来抄去，这就是没想清楚这个功能能满足用户什么..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://bornforthis.cn/gzh.jpg"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2025-09-26T00:51:48.000Z"}],["meta",{"property":"article:author","content":"bornforthis"}],["meta",{"property":"article:published_time","content":"2025-09-25T23:11:07.000Z"}],["meta",{"property":"article:modified_time","content":"2025-09-26T00:51:48.000Z"}]]},"git":{"createdTime":1669634625000,"updatedTime":1758847908000,"contributors":[{"name":"AndersonHJB","username":"AndersonHJB","email":"cleland1432803776@icloud.com","commits":13,"url":"https://github.com/AndersonHJB"},{"name":"AI悦创","username":"","email":"cleland1432803776@icloud.com","commits":1}],"changelog":[{"hash":"bb679f2035771e66ec0f444be013ebccb5c25c56","time":1758847908000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"docs(数据分析思维与实战23讲): 添加第23讲用户研究内容及图片资源"},{"hash":"be749796a4e8e01a168c2de021a7bee598d7b1cc","time":1758813358000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"docs(数据分析思维与实战23讲): 添加第22课数据仓库和第23课用户研究内容"},{"hash":"1bf8ef0014b4b72bca7eebd749390f306fe02ab5","time":1758803033000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"docs: 添加数据分析课程相关图片和更新文章内容"},{"hash":"17ef58c9cdcab06b93afdb348f078c3cf624d807","time":1758797317000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"docs: 添加图片资源并更新文档内容"},{"hash":"a44f645ebd9aae658b7cb10f6cb11490fddfdb0c","time":1752398759000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"docs(食谱): 更新澄面版本说明并添加鸡蛋灌饼和手抓饼文档"},{"hash":"70353fead4a0a1bfadb60ece94c0f3a9f80bfc08","time":1746926862000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更新文件夹名称"},{"hash":"ae8a442bae9aa264fee20e42267291df3a74b667","time":1746879162000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更新食谱文档，优化标签和步骤格式"},{"hash":"9bfdcd8407ca12cf09f385c602eb1c60cc5f3c56","time":1745906987000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"新增 Vuepress 侧边栏自定义文档，包含自动生成侧边栏的说明及相关信息"},{"hash":"4d098f34b968c7f9162e7d143141d46669c76d6e","time":1745325668000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"Add articles on programming and cooking: \\"Can computer programs really kill people?\\" and \\"清蒸鲈鱼\\""},{"hash":"1c35a6532eb53bd6ed2f2afd6f70564646e80c01","time":1744328990000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"去掉head"},{"hash":"cbb3a0f217ea57089ad27386b3127e612324b609","time":1675049774000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"update"},{"hash":"76989bb701c8ac79bbc7e2e46050c8b08855befd","time":1670605630000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"86c50aa64ad737c1db38d74dbb5ec22bb6c5bbeb","time":1670575429000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"027da62f7fafa8a29d6f7ba006e9bff7ac22acfe","time":1669634625000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"first commit"}]},"readingTime":{"minutes":8.39,"words":2516},"filePathRelative":"column/数据分析思维与实战23讲/23.md","excerpt":"<p>今天我主要介绍用户研究，用户研究是分析师日常必须要掌握的一项技能。</p>\\n<p>本课时内容分为三部分：</p>\\n<ul>\\n<li>\\n<p>什么是用户研究；</p>\\n</li>\\n<li>\\n<p>用户研究的步骤和关键点；</p>\\n</li>\\n<li>\\n<p>用户研究的注意事项；</p>\\n</li>\\n</ul>\\n<h2>1. 什么是用户研究</h2>\\n<p>用户研究是一种职业意识，任何人都应该具备用户研究思维，包括以下方面。</p>\\n<h3>1.1 这个功能能满足用户什么需求？</h3>\\n<p>大部分 App 都是抄来抄去，这就是没想清楚这个功能能满足用户什么需求。比如爱奇艺、腾讯、优酷三家都是对方的竞品，现在 App 上的功能大多一样。再比如信息流，头条之前有订阅、关注功能，现在其他竞品差不多也都有。</p>","copyright":{"author":"bornforthis"},"autoDesc":true}`),a={name:`23.md`};function o(r,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[n(`<p>今天我主要介绍用户研究，用户研究是分析师日常必须要掌握的一项技能。</p><p>本课时内容分为三部分：</p><ul><li><p>什么是用户研究；</p></li><li><p>用户研究的步骤和关键点；</p></li><li><p>用户研究的注意事项；</p></li></ul><h2 id="_1-什么是用户研究" tabindex="-1"><a class="header-anchor" href="#_1-什么是用户研究"><span>1. 什么是用户研究</span></a></h2><p>用户研究是一种职业意识，任何人都应该具备用户研究思维，包括以下方面。</p><h3 id="_1-1-这个功能能满足用户什么需求" tabindex="-1"><a class="header-anchor" href="#_1-1-这个功能能满足用户什么需求"><span>1.1 这个功能能满足用户什么需求？</span></a></h3><p>大部分 App 都是抄来抄去，这就是没想清楚这个功能能满足用户什么需求。比如爱奇艺、腾讯、优酷三家都是对方的竞品，现在 App 上的功能大多一样。再比如信息流，头条之前有订阅、关注功能，现在其他竞品差不多也都有。</p><h3 id="_1-2-用户当前反馈最多的问题是什么-哪些可以重点解决" tabindex="-1"><a class="header-anchor" href="#_1-2-用户当前反馈最多的问题是什么-哪些可以重点解决"><span>1.2 用户当前反馈最多的问题是什么？哪些可以重点解决？</span></a></h3><p>App 作为一个产品，用户肯定有各种各样的反馈，反馈最多的问题是什么？占比多少？比如反馈的 10 个问题里面占比最多的是 A 问题， A 问题到底能不能解决？不能彻底解决，能不能变相解决？用户抱怨最多的那个问题一定是你产品最大的问题。</p><h3 id="_1-3-针对上面两个问题-需要进行线上或者线下调研-获得数据反馈" tabindex="-1"><a class="header-anchor" href="#_1-3-针对上面两个问题-需要进行线上或者线下调研-获得数据反馈"><span>1.3 针对上面两个问题，需要进行线上或者线下调研，获得数据反馈</span></a></h3><p>用户研究最后会落地到你怎么去解决这些问题，你只有去跟用户聊或者进行问卷的投放获得一些数据反馈，才能够让你的产品拼到最后。头部玩家重大的 Bug 肯定是没有的，都是拼一些细节。</p><p>用户研究我们知道了，那什么时候做用户研究呢？其实用户研究贯穿整个项目生命周期。</p><ul><li><p>项目前期：用户需求情况、用户基础画像情况、用户对于低价商品的迫切度。</p></li><li><p>项目中期：用户行为习惯。</p></li><li><p>项目后期：用户对产品的反馈点、竞品使用情况。</p></li></ul><p>我们做的所有一切都是为了更好地了解用户，然后与数据分析相辅相成，因为有时候数据角度并不能很好地反映用户的行为及原因。比如之前有一节课说拼多多，在之前，我相信很多同学手机里面没安装拼多多，但作为分析师，我们还是要去看每个爆款 App，去了解它为什么成功，了解后就一定能够能找到它自身的亮点。有时候我们真的离用户太远了，所以只从数据角度真的没有办法去解释，你要去做真实的用户调研。</p><p>用户研究在项目启动前就应该开展，并且要快于其他业务方。如果等到那个项目都启动了，实际上该做的也做了，你这个时候再去启动，一个月之后出报告，价值不大，所以这非常考验用户研究人员的先见性和实操性。这里面我说一个大家常见的误解：大多人觉得用户研究这个东西好像没什么用，就随便做报告，好像看了就看了，但不是这么回事。</p><h2 id="_2-用户研究的步骤和关键点" tabindex="-1"><a class="header-anchor" href="#_2-用户研究的步骤和关键点"><span>2. 用户研究的步骤和关键点</span></a></h2><p>用户研究可以分为 3 个步骤。</p><ol><li><p>制定研究目的：有良好的背景和具体的问题</p></li><li><p>选择研究方法：定量和定性方法要对</p></li><li><p>研究结论产出：精而快</p></li></ol><p>举个例子：</p><p>项目：今日头条 App 新用户留存专项</p><p>项目背景：2015 年今日头条 App 新用户次留、7 留与竞品相比，留存均低 5% 绝对值，并且新用户流失速度要高于竞品，因此要在数据分析基础上，产品运营优化，提升用户留存 5% 绝对值。</p><p>在真实的项目过程中，除了数据分析师，肯定还要有用研人员的参与。所以同样针对这个项目，用研人员分为哪几步？我们先看一看数据分析师分为哪几步，之前我们都讲过，所以这边就粗略回顾。</p><figure><img src="/assets/Ciqc1F82RpyAaPRcAACRehxt7vo077-CQU0Clrk.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>第一个阶段就是整体分析；第二阶段寻找优化切入点，一般是 1-2 个；第三阶段就是不断地重复前面两个阶段，然后进行一些其他的分析。</p><p>作为用研人员在这里面也有三个阶段。</p><h3 id="_2-1-第一阶段-制定研究目的" tabindex="-1"><a class="header-anchor" href="#_2-1-第一阶段-制定研究目的"><span>2.1 第一阶段：制定研究目的</span></a></h3><p>在前期，用研人员要快速了解到当前的问题现状，制定思维脑图（下图所示）。所有人做的都是一件事，只不过落地方式不一样，更好地了解用户和产品，越能更好地解决问题。</p><figure><img src="/assets/Ciqc1F82RqqANrxAAAByga5JlDk600-BiiRVitB.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><h3 id="_2-2-第二阶段-确定研究方法" tabindex="-1"><a class="header-anchor" href="#_2-2-第二阶段-确定研究方法"><span>2.2 第二阶段：确定研究方法</span></a></h3><p>整个用研分为定量和定性两种，如下图所示。</p><figure><img src="/assets/CgqCHl82RrKAPhEvAABw26VpQmU528-DCRUcovE.png" alt="（图片来源：网络百度）" tabindex="0" loading="lazy"><figcaption>（图片来源：网络百度）</figcaption></figure><p>在真实工作过程中没这么复杂，主要是以用户访谈和调查问卷为主。</p><ul><li><p>用户访谈：定性，把用户约过来然后跟他聊（单纯的聊天也有很多技巧）。</p></li><li><p>调查问卷：定量，比如在信息流里面，我投放一份问卷，然后给用户一些奖励。有一些忠实用户或者一些追求利益的用户就会填写问卷，当你的样本量足够大之后，这个数据就可以拿来用。</p></li></ul><p>研究方法这里面最重要的点是什么？</p><ul><li><p>定性：约用户面聊，侧重于 Why 和 How，问得很细很深。</p></li><li><p>定量：投放问卷，侧重于 What、When、Where。</p></li></ul><p>对于一款产品，如果本身产品经理、分析师离普通用户太远，就非常有必要做定性分析。定量分析非常注重样本量，同时要确保问卷设计的专业性。无论是定性还是定量，都需要一定的物质激励，这样才能保证很快的产出。</p><p>我个人觉得用户研究这件事的意义要远远大于一次营销活动，可能很多公司觉得没钱做用研，比如说给用户一些物质激励。其实你有一些小小的奖励，可能很多用户也都看不上。有一些营销活动很多时候做了就做了，没留下什么价值，大多是薅羊毛，对比而言没有用户研究价值大。</p><h3 id="_2-3-第三阶段-结论产出" tabindex="-1"><a class="header-anchor" href="#_2-3-第三阶段-结论产出"><span>2.3 第三阶段：结论产出</span></a></h3><p>在结论产出这一块，当前的现状就是很多用研报告追求大而全，从开始做到最后输出要一个月。我相信大部分公司的节奏都很快，一个月期间，项目可能都已经进行了调整。比较好的节奏就是两周内输出结论。</p><p>因为这样：</p><ul><li><p>能够和分析师的数据分析报告一起输出，定量定性结合；</p></li><li><p>能够在最迫切需要的时候给出，价值最大化；</p></li><li><p>能够很好地融入整个项目团队，使做的事情更有意义。</p></li></ul><h2 id="_3-用户研究的注意事项" tabindex="-1"><a class="header-anchor" href="#_3-用户研究的注意事项"><span>3. 用户研究的注意事项</span></a></h2><p>在用户研究实施时要注意以下事项：</p><ul><li><p>用户说什么不重要，更加重要的是用户为何会这样说；</p></li><li><p>不要直接问用户喜欢什么，用户对他们的心理过程根本就不了解，这里面最好的工作法是田野工作法（现场调研）；</p></li><li><p>定性分析注重用户分类，定量分析注重样本量和样本代表性；</p></li><li><p>结束访谈后，尽快整理成文档，寻找琐碎记忆；</p></li><li><p>用户报告追求精而快；</p></li></ul><p>接下来我们看看用户研究的未来。短期来看，用户研究这个职业是存在的，大公司一般都有用研团队，小公司基本没有。主要讲究用户研究+MVP 思想（即围绕目标迅速搭建一个通用的简单模型给业务）这里不需要系统化，解决问题即可。</p><p>长期来看，用户研究是一种职业意识，人人都是用户研究分析师，常常跟数据打交道的我们一定要知道用户习惯。</p><p>那用户研究和分数据析师是什么关系呢？数据分析师一定要有用户研究的意识，常见的做法是：</p><ul><li><p>每天体验产品，看核心数据；</p></li><li><p>每周看客服数据；</p></li><li><p>对于费解的数据分析结论，分析师需推动用户研究人员去做用户访谈或者问卷；</p></li><li><p>新项目启动期，如果要去线下了解用户，分析师要抓住这些机会。</p></li></ul><p>今天的课程就到这里，你对用户研究有什么问题？可以写在下方留言与我交流。</p><details class="hint-container details"><summary>公众号：AI悦创【二维码】</summary><figure><img src="/gzh.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure></details><div class="hint-container info"><p class="hint-container-title">AI悦创·编程一对一</p><p>AI悦创·推出辅导班啦，包括「Python 语言辅导班、C++ 辅导班、java 辅导班、算法/数据结构辅导班、少儿编程、pygame 游戏开发、Web、Linux」，招收学员面向国内外，国外占 80%。全部都是一对一教学：一对一辅导 + 一对一答疑 + 布置作业 + 项目实践等。当然，还有线下线上摄影课程、Photoshop、Premiere 一对一教学、QQ、微信在线，随时响应！微信：Jiabcdefh</p><p>C++ 信息奥赛题解，长期更新！长期招收一对一中小学信息奥赛集训，莆田、厦门地区有机会线下上门，其他地区线上。微信：Jiabcdefh</p><p>方法一：<a href="http://wpa.qq.com/msgrd?v=3&amp;uin=1432803776&amp;site=qq&amp;menu=yes" target="_blank" rel="noopener noreferrer">QQ</a></p><p>方法二：微信：Jiabcdefh</p></div><figure><img src="/zsxq.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure>`,52)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};